                int mediaId = extractMediaId(path);
                if (mediaId <= 0) {
                    response = new Response(HttpStatus.BAD_REQUEST, ContentType.JSON, "{\"message\":\"Invalid mediaId\"}");
                } else {
                    response = mediaController.removeFavorite(userId, mediaId);
