    private static Object readField(Object obj, String... names) {
        for (String n : names) {
            Class<?> c = obj.getClass();
            while (c != null) {
                try {
                    Field f = c.getDeclaredField(n);
                    f.setAccessible(true);
                    return f.get(obj);
